import Foundation

enum AppLanguage: String, CaseIterable {
    case chineseSimplified = "zh-Hans"
    case english = "en"
    case japanese = "ja"
    case korean = "ko"
    case german = "de"

    var displayName: String {
        switch self {
        case .chineseSimplified: return "简体中文"
        case .english: return "English"
        case .japanese: return "日本語"
        case .korean: return "한국어"
        case .german: return "Deutsch"
        }
    }
}

extension Notification.Name {
    // Keep the internal notification identifier stable for compatibility.
    static let appLanguageDidChange = Notification.Name("NagaController.AppLanguageDidChange")
}

/// Runtime localization used by this menu-bar app. Keeping language selection
/// independent from macOS makes testing predictable and avoids changing the
/// user's system language. Missing entries deliberately fall back to the
/// existing Simplified Chinese source string instead of showing a raw key.
enum L10n {
    private static let defaultsKey = "appLanguage"

    private(set) static var language: AppLanguage = {
        if let raw = UserDefaults.standard.string(forKey: defaultsKey),
           let saved = AppLanguage(rawValue: raw) {
            return saved
        }
        let preferred = Locale.preferredLanguages.first?.lowercased() ?? "en"
        if preferred.hasPrefix("zh") { return .chineseSimplified }
        if preferred.hasPrefix("ja") { return .japanese }
        if preferred.hasPrefix("ko") { return .korean }
        if preferred.hasPrefix("de") { return .german }
        return .english
    }()

    /// True once the user has explicitly chosen a language (first-launch
    /// welcome picker or the popover menu); false on a fresh install where
    /// the language was only inferred from the system locale.
    static var hasPersistedLanguage: Bool {
        UserDefaults.standard.string(forKey: defaultsKey) != nil
    }

    static func setLanguage(_ newLanguage: AppLanguage) {
        // Always persist: on first launch the choice may equal the inferred
        // system language, and skipping the write would re-show the welcome
        // picker on every start.
        UserDefaults.standard.set(newLanguage.rawValue, forKey: defaultsKey)
        guard newLanguage != language else { return }
        language = newLanguage
        NotificationCenter.default.post(name: .appLanguageDidChange, object: newLanguage)
    }

    static func text(_ source: String) -> String {
        if let localized = supplementalTables[language]?[source] { return normalizedPunctuation(in: localized) }
        if let localized = tables[language]?[source] { return normalizedPunctuation(in: localized) }
        guard language != .chineseSimplified else { return normalizedPunctuation(in: source) }
        // English is the completeness baseline. A missing secondary phrase in
        // another translation must never leak a Chinese source key into that UI.
        return normalizedPunctuation(in: supplementalTables[.english]?[source] ?? tables[.english]?[source] ?? source)
    }

    private static func normalizedPunctuation(in value: String) -> String {
        value.replacingOccurrences(of: "...", with: "…")
    }

    static func format(_ source: String, _ arguments: CVarArg...) -> String {
        String(format: text(source), locale: Locale(identifier: language.rawValue), arguments: arguments)
    }

    static func hasTranslation(_ source: String, for language: AppLanguage) -> Bool {
        language == .chineseSimplified || supplementalTables[language]?[source] != nil || tables[language]?[source] != nil
    }

    static func hasCompleteTranslation(for language: AppLanguage) -> Bool {
        guard language != .chineseSimplified else { return true }
        let baseline = Set(tables[.english]?.keys ?? Dictionary<String, String>().keys)
            .union(supplementalTables[.english]?.keys ?? Dictionary<String, String>().keys)
        let localized = Set(tables[language]?.keys ?? Dictionary<String, String>().keys)
            .union(supplementalTables[language]?.keys ?? Dictionary<String, String>().keys)
        guard baseline.isSubset(of: localized) else { return false }
        guard language != .english else { return true }
        let english = tables[.english] ?? [:]
        let mustBeLocalized: Set<String> = [
            "+ 新建自定义分组", "创建一个可命名的输入分组，然后在分组中读取新按键",
            "读取默认按键或自定义分组中的新输入。每个来源都使用三次一致性校验，每次限时 20 秒；只读取信号，不写入鼠标配置。",
            "自定义分组", "所属分组", "读取新输入", "删除这个空分组", "设备配置合并冲突",
            "产品名称", "最大输入报告长度", "设备身份识别规则", "启用增强识别",
            "VID/PID 是不可删除的基础条件。启用的增强条件必须全部匹配；任何一项不匹配或缺失时，安全回退到 VID/PID。",
            "同型号实例区分字段", "无法保存身份规则"
        ]
        return mustBeLocalized.allSatisfy { key in
            guard let translated = tables[language]?[key], let englishValue = english[key] else { return false }
            return translated != englishValue
        }
    }

    /// Runs deterministic display assertions without persisting a different
    /// user language or posting a UI rebuild notification.
    static func withTemporaryLanguage<T>(_ temporaryLanguage: AppLanguage, _ body: () -> T) -> T {
        let previous = language
        language = temporaryLanguage
        defer { language = previous }
        return body()
    }

